// DETERMINISTIC CONTEXT MANIFEST
// Uses git commit hash + file checksums for stable source tracking

const workflowVersion = '2.0.0';
const runId = new Date().toISOString().split('T')[0].replace(/-/g, '');

// Use absolute path - UPDATE THIS to your actual path
const baseDir = 'C:/Users/kyrian/Documents/contentCreator';

// Define stable context sources with dynamic paths
const contextManifest = {
  version: workflowVersion,
  run_id: runId,
  sources: [
    {
      path: baseDir + '/context/services/custom-ai.md',
      category: 'services',
      priority: 1,
      required: true
    },
    {
      path: baseDir + '/context/services/automation.md',
      category: 'services',
      priority: 1,
      required: true
    },
    {
      path: baseDir + '/context/brand/voice.md',
      category: 'brand',
      priority: 1,
      required: true
    },
    {
      path: baseDir + '/context/brand/rules.md',
      category: 'brand',
      priority: 1,
      required: true
    }
  ],
  created_at: new Date().toISOString()
};

return {
  json: contextManifest
};

// Extract individual source items for processing
const manifest = $input.first().json;
const sources = manifest.sources || [];

return sources.map(source => ({
  json: {
    ...source,
    manifest_version: manifest.version,
    run_id: manifest.run_id
  }
}));

// Read file content from previous node and normalize
const sourceInfo = $('Split Sources').item.json;
const fileData = $input.first().json;

// Get file content from readWriteFile node
const rawContent = fileData.data || '';
const filePath = sourceInfo.path;
const fileExists = rawContent && rawContent.length > 0;

// HARD VALIDATION: Schema enforcement
if (sourceInfo.required && !fileExists) {
  throw new Error(`CRITICAL: Required context file missing: ${filePath}`);
}

// Normalize content structure
const normalized = {
  source: {
    path: filePath,
    category: sourceInfo.category,
    priority: sourceInfo.priority,
    required: sourceInfo.required
  },
  content: {
    raw: rawContent,
    word_count: rawContent.split(/\s+/).filter(w => w.length > 0).length,
    char_count: rawContent.length,
    sections: rawContent.split('\n\n').filter(s => s.trim().length > 0)
  },
  metadata: {
    manifest_version: sourceInfo.manifest_version,
    run_id: sourceInfo.run_id,
    processed_at: new Date().toISOString(),
    file_exists: fileExists,
    validation_passed: fileExists
  }
};

// Pre-flight content validation
if (normalized.content.word_count < 10) {
  throw new Error(`VALIDATION FAILED: Context too short: ${filePath}`);
}

return { json: normalized };

// MERGE ALL CONTEXTS BEFORE BATCHING
// This ensures consistent input to the model

const allContexts = $input.all();

// Group by category for structured prompting
const contextsByCategory = {};
let totalWordCount = 0;

for (const item of allContexts) {
  const ctx = item.json;
  const category = ctx.source.category;

  if (!contextsByCategory[category]) {
    contextsByCategory[category] = [];
  }

  contextsByCategory[category].push(ctx);
  totalWordCount += ctx.content.word_count;
}

// Build merged context with metadata
const mergedContext = {
  run_metadata: {
    run_id: allContexts[0].json.metadata.run_id,
    manifest_version: allContexts[0].json.metadata.manifest_version,
    total_sources: allContexts.length,
    total_word_count: totalWordCount,
    merged_at: new Date().toISOString()
  },
  contexts_by_category: contextsByCategory,
  generation_config: {
    variations_per_batch: 5,
    word_count_min: 120,
    word_count_max: 180,
    hashtag_count: 4,
    emoji_max: 2
  }
};

return { json: mergedContext };

// PRE-MODEL GUARDRAILS
// Validate and sanitize before sending to Claude

const merged = $input.first().json;
const config = merged.generation_config;

// GUARDRAIL 1: Size limits
if (merged.run_metadata.total_word_count > 50000) {
  throw new Error('GUARDRAIL: Context exceeds token budget');
}

// GUARDRAIL 2: Required categories
const requiredCategories = ['services', 'brand'];
for (const cat of requiredCategories) {
  if (!merged.contexts_by_category[cat]) {
    throw new Error(`GUARDRAIL: Missing required category: ${cat}`);
  }
}

// GUARDRAIL 3: Sanitize content (remove potential injection attacks)
function sanitize(text) {
  // Remove potentially dangerous patterns
  return text
    .replace(/\$\{[^}]*\}/g, '') // Template literals
    .replace(/eval\(/g, '') // Eval attempts
    .replace(/<script[^>]*>.*?<\/script>/gi, ''); // Script tags
}

// Sanitize all content
for (const category in merged.contexts_by_category) {
  for (const ctx of merged.contexts_by_category[category]) {
    ctx.content.raw = sanitize(ctx.content.raw);
  }
}

// Build structured prompt with clear spec
const structuredPrompt = {
  system_role: 'LinkedIn content strategist for AI-Whisperers',
  brand_voice: {
    tone: 'Professional yet approachable',
    principles: ['Evidence-based', 'No hype', 'Builder-focused', 'Pragmatic']
  },
  content_distribution: {
    services: '60%',
    educational: '40%'
  },
  strict_rules: {
    word_count: `${config.word_count_min}-${config.word_count_max}`,
    max_emojis: config.emoji_max,
    hashtag_count: config.hashtag_count,
    forbidden_words: ['revolutionary', 'game-changing', 'disruptive', 'transform your']
  },
  context_sources: merged.contexts_by_category,
  output_schema: {
    type: 'object',
    required: ['posts'],
    properties: {
      posts: {
        type: 'array',
        minItems: config.variations_per_batch,
        maxItems: config.variations_per_batch,
        items: {
          type: 'object',
          required: ['variation', 'hook', 'body', 'cta', 'hashtags', 'word_count'],
          properties: {
            variation: { type: 'string', enum: ['service-showcase', 'tool-tutorial', 'concept-explained', 'case-study', 'how-to'] },
            hook: { type: 'string', minLength: 10 },
            body: { type: 'string', minLength: 50 },
            cta: { type: 'string', minLength: 10 },
            hashtags: { type: 'array', minItems: 4, maxItems: 4 },
            word_count: { type: 'number', minimum: config.word_count_min, maximum: config.word_count_max }
          }
        }
      }
    }
  },
  run_metadata: merged.run_metadata
};

return { json: structuredPrompt };

