// HARD VALIDATION: Parse and validate model output
// Reject invalid responses BEFORE splitting

const claudeResponse = $input.first().json;
const promptData = $('Pre-Model Guardrails').first().json;

let responseText = '';
try {
  responseText = claudeResponse.content[0].text;
} catch (error) {
  throw new Error('VALIDATION FAILED: Invalid Claude response structure');
}

let parsedData;
try {
  // Try direct parse
  parsedData = JSON.parse(responseText);
} catch (e) {
  // Try extracting from code block
  const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/) || responseText.match(/```\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    try {
      parsedData = JSON.parse(jsonMatch[1]);
    } catch (e2) {
      throw new Error(`VALIDATION FAILED: Cannot parse JSON from Claude response`);
    }
  } else {
    throw new Error('VALIDATION FAILED: No valid JSON found in response');
  }
}

// HARD VALIDATION: Schema enforcement
if (!parsedData.posts || !Array.isArray(parsedData.posts)) {
  throw new Error('VALIDATION FAILED: Missing or invalid posts array');
}

const config = promptData.strict_rules;
const forbiddenWords = config.forbidden_words;
const validationResults = [];

for (let i = 0; i < parsedData.posts.length; i++) {
  const post = parsedData.posts[i];
  const issues = [];

  // Required fields
  if (!post.variation || !post.hook || !post.body || !post.cta || !post.hashtags || post.word_count === undefined) {
    throw new Error(`VALIDATION FAILED: Post ${i} missing required fields`);
  }

  // Word count validation
  const wordCountMin = parseInt(config.word_count.split('-')[0]);
  const wordCountMax = parseInt(config.word_count.split('-')[1]);
  if (post.word_count < wordCountMin || post.word_count > wordCountMax) {
    issues.push(`Word count ${post.word_count} outside range ${wordCountMin}-${wordCountMax}`);
  }

  // Hashtag validation
  if (!Array.isArray(post.hashtags) || post.hashtags.length !== config.hashtag_count) {
    issues.push(`Must have exactly ${config.hashtag_count} hashtags, got ${post.hashtags?.length || 0}`);
  }

  // Forbidden words check
  const fullText = `${post.hook} ${post.body} ${post.cta}`.toLowerCase();
  const foundForbidden = forbiddenWords.filter(word => fullText.includes(word.toLowerCase()));
  if (foundForbidden.length > 0) {
    issues.push(`Contains forbidden words: ${foundForbidden.join(', ')}`);
  }

  // Emoji count check
  const emojiRegex = /[\p{Emoji}]/gu;
  const emojiCount = (fullText.match(emojiRegex) || []).length;
  if (emojiCount > config.max_emojis) {
    issues.push(`Too many emojis: ${emojiCount} (max ${config.max_emojis})`);
  }

  // Calculate quality score
  const qualityScore = Math.max(0, 100 - (issues.length * 20));
  const status = qualityScore >= 70 ? 'APPROVED' : 'NEEDS_REVISION';

  // Generate version tag
  const versionTag = `v${promptData.run_metadata.manifest_version}-${promptData.run_metadata.run_id}-${i}`;

  validationResults.push({
    post_id: `${post.variation}-${versionTag}`,
    version: versionTag,
    variation: post.variation,
    hook: post.hook,
    body: post.body,
    cta: post.cta,
    hashtags: post.hashtags,
    full_text: `${post.hook}\n\n${post.body}\n\n${post.cta}\n\n${post.hashtags.map(tag => '#' + tag).join(' ')}`,
    word_count: post.word_count,
    emoji_count: emojiCount,
    quality_score: qualityScore,
    status: status,
    issues: issues,
    metadata: {
      manifest_version: promptData.run_metadata.manifest_version,
      run_id: promptData.run_metadata.run_id,
      validated_at: new Date().toISOString(),
      validation_passed: issues.length === 0
    }
  });
}

return validationResults.map(result => ({ json: result }));

// UNIFIED NORMALIZER: Same logic for both branches
// Only difference is storage destination

const post = $input.first().json;
const batchDate = post.metadata.run_id;
const isApproved = post.status === 'APPROVED';
const subdir = isApproved ? 'approved' : 'needs-revision';

// Use absolute path - UPDATE THIS to your actual path
const baseDir = 'C:/Users/kyrian/Documents/contentCreator';

// Build file path
const filePath = baseDir + '/generated-posts/batch-' + batchDate + '/' + subdir + '/' + post.post_id + '.md';

// Build content with versioning
let content = `---
post_id: ${post.post_id}
version: ${post.version}
variation: ${post.variation}
status: ${post.status}
quality_score: ${post.quality_score}
word_count: ${post.word_count}
emoji_count: ${post.emoji_count}
manifest_version: ${post.metadata.manifest_version}
run_id: ${post.metadata.run_id}
generated_at: ${post.metadata.validated_at}
validation_passed: ${post.metadata.validation_passed}
---\n\n`;

if (isApproved) {
  content += `# ${post.variation}\n\n`;
  content += `## Hook\n${post.hook}\n\n`;
  content += `## Body\n${post.body}\n\n`;
  content += `## CTA\n${post.cta}\n\n`;
  content += `## Hashtags\n${post.hashtags.map(tag => '#' + tag).join(' ')}\n\n`;
  content += `---\n\n## READY TO POST\n\n${post.full_text}\n`;
} else {
  content += `# ⚠️ NEEDS REVISION\n\n`;
  content += `## Issues\n${post.issues.map((issue, i) => `${i+1}. ${issue}`).join('\n')}\n\n`;
  content += `## Content\n\n${post.full_text}\n`;
}

return {
  json: {
    file_path: filePath,
    file_content: content,
    post_id: post.post_id,
    version: post.version,
    status: post.status
  }
};

